"use strict";
// 联系微信二维码（图片内嵌为 data URI，删除原 png 不影响显示）
var WECHAT_QR = "data:image/png;base64,";

function showContactQr() {
  if (document.getElementById("qrOverlay")) return;
  var ov = document.createElement("div");
  ov.id = "qrOverlay";
  ov.className = "qr-overlay";
  ov.innerHTML = '<div class="qr-card">' +
    '<div class="qr-head"><span>微信联系 · Fedariovo-321</span><button class="qr-close" type="button" title="关闭">✕</button></div>' +
    '<div class="qr-img-box"></div>' +
    '<p class="qr-tip">长按/截图保存二维码，微信扫码加好友<br>点击空白处或右上角 ✕ 关闭</p>' +
    '</div>';
  var box = ov.querySelector(".qr-img-box");
  var img = document.createElement("img");
  img.className = "qr-img";
  img.src = WECHAT_QR;
  img.alt = "微信二维码";
  box.appendChild(img);
  ov.addEventListener("click", function (e) { if (e.target === ov) ov.remove(); });
  var closeBtn = ov.querySelector(".qr-close");
  if (closeBtn) closeBtn.addEventListener("click", function () { ov.remove(); });
  document.addEventListener("keydown", function (e) { if (ov.isConnected && e.key === "Escape") ov.remove(); }, { once: true });
  document.body.appendChild(ov);
}

document.querySelectorAll(".wechat-link").forEach(function (el) {
  el.addEventListener("click", function (e) { e.preventDefault(); e.stopPropagation(); showContactQr(); });
});

// ===== 版本信息：显示“当前版本”与“最新版本”（实时监测更新源） =====
function refreshVersionInfo() {
  try {
    fetch("/api/update/check").then(function (r) { return r.json(); }).then(function (d) {
      var cur = document.getElementById("verCurrent");
      var lat = document.getElementById("verLatest");
      if (cur) cur.textContent = (d && d.current) ? d.current : "-";
      if (lat) {
        if (d && d.configured === false) { lat.textContent = "未配置更新源"; lat.classList.remove("ver-update"); }
        else if (d && d.latest) {
          lat.textContent = d.latest + (d.hasUpdate ? "（可更新）" : "");
          if (d.hasUpdate) { lat.classList.add("ver-update"); } else { lat.classList.remove("ver-update"); }
        }
        else { lat.textContent = "-"; lat.classList.remove("ver-update"); }
      }
    }).catch(function () {});
  } catch (e) {}
}
function initVersionInfo() {
  refreshVersionInfo();
  setInterval(refreshVersionInfo, 60000); // 每分钟实时监测最新版本
}
if (document.readyState === "loading") { document.addEventListener("DOMContentLoaded", initVersionInfo); }
else { initVersionInfo(); }